{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team enters the ruined city.",
      "visual_description": "A shattered royal gate stands half-collapsed, rusted banners sagging from broken poles. Mara the Cartographer leads, compass in hand, past crumbling walls and charred trees.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The Oracle Lamp sits on a cracked stone, its single eye glowing as it points its flame toward a spiraling tower, overgrown with black thorn vines.", "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople flee through the square.",
      "visual_description": "A wide cobblestone square is empty except for bundles of abandoned belongings; a sign sways above a boarded-up fountain. The team watches from a shadowed alcove.", "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Armored patrols march down a main avenue.",
      "visual_description": "Rows of figures in dented armor clank past, their helmets hiding all expression, banners tattered. Mara presses the team against a wall.", "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector is found slumped at a desk.",
      "visual_description": "In a roofless building, the Sleeping Tax Collector snores on a ledger, stamped papers fluttering from his sleeves. The Oracle Lamp hovers nearby.", "characters": ["sleeping_tax_collector", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The Tin Fox scouts a ruined market.",
      "visual_description": "The Tin Fox's blue eyes scan a collapsed market stall, its key-wind tail twitching. Dusty crates and torn cloth surround it.", "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of dragons are sketched on a wall.",
      "visual_description": "Crude chalk drawings of winged creatures cover an inner wall. Mara pauses to trace one, her ink-stained fingers trembling.", "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door shimmers between two columns.",
      "visual_description": "A translucent door flickers with shifting runes in an archway of worn stone. The Glass Diver approaches, helmet reflecting the light.", "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The team tests the magic door with a coin.",
      "visual_description": "Mara tosses a small copper coin toward the door; it passes through with a faint ripple. The Oracle Lamp flares.", "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector wakes briefly.",
      "visual_description": "The Sleeping Tax Collector stirs, blinks, yawns, then flops back onto his ledger. A stamped paper sticks to his cheek.", "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "A castle gate looms ahead, guarded by statues.",
      "visual_description": "Two stone statues of robed figures flank a massive iron gate. The Glass Diver swims a small mirror to see beyond.", "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp reveals a hidden passage.",
      "visual_description": "The Oracle Lamp's eye casts a beam onto a false wall. Dust and cobwebs mask a narrow stairway down.", "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The team descends into a crypt-like undercroft.",
      "visual_description": "Low ceiling, damp stone, and old royal shields hung on pillars. The Tin Fox's eyes glow in the dark.", "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "A false door triggers a falling portcullis.",
      "visual_description": "The Glass Diver touches a lever; a portcullis crashes behind them, sealing the exit. Dust clouds rise.", "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Sleeping Tax Collector is carried along.",
      "visual_description": "The Tin Fox tugs at the Sleeping Tax Collector's sleeve. The Glass Diver hoists the dozing figure onto his shoulder.", "characters": ["sleeping_tax_collector", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The team reaches the old city bridge.",
      "visual_description": "A stone bridge spans a dry riverbed, broken archways and torn ropes dangling. Armored patrols close from behind.", "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver shatters a mirror to slow pursuers.",
      "visual_description": "The Glass Diver throws a small mirror onto the bridge; it explodes into razor shards, forcing the patrols to halt.", "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Escape across the bridge into the twilight.",
      "visual_description": "The team dashes across the last span of the bridge, broken city behind them, open plains ahead. The Oracle Lamp glows softly in the dusk.", "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

